CREATE TABLE records (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  slug TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  summary TEXT NOT NULL,
  outcome TEXT NOT NULL CHECK (outcome IN ('proved', 'disproved', 'discovered', 'formalized', 'benchmark')),
  novelty TEXT NOT NULL CHECK (novelty IN ('new-result', 'human-ai', 'rediscovery', 'formalization', 'capability')),
  domain TEXT NOT NULL,
  event_date TEXT NOT NULL,
  ai_system TEXT NOT NULL,
  ai_role TEXT NOT NULL,
  human_role TEXT NOT NULL,
  verification TEXT NOT NULL,
  verification_tier TEXT NOT NULL CHECK (verification_tier IN ('formal', 'published', 'expert', 'reported')),
  caveat TEXT NOT NULL,
  featured INTEGER NOT NULL DEFAULT 0 CHECK (featured IN (0, 1)),
  tags_json TEXT NOT NULL DEFAULT '[]',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE sources (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  record_id INTEGER NOT NULL REFERENCES records(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('paper', 'formal-proof', 'announcement', 'expert-review', 'project', 'problem')),
  title TEXT NOT NULL,
  url TEXT NOT NULL,
  is_primary INTEGER NOT NULL DEFAULT 1 CHECK (is_primary IN (0, 1)),
  UNIQUE(record_id, url)
);

CREATE INDEX records_event_date_idx ON records(event_date DESC);
CREATE INDEX records_outcome_idx ON records(outcome);
CREATE INDEX records_domain_idx ON records(domain);
CREATE INDEX records_verification_idx ON records(verification_tier);
CREATE INDEX sources_record_id_idx ON sources(record_id);


