INSERT INTO records
  (slug, title, summary, outcome, novelty, domain, event_date, ai_system, ai_role, human_role, verification, verification_tier, caveat, featured, tags_json)
VALUES
  ('feige-conjecture', 'Feige’s conjecture on sums of nonnegative random variables', 'A short proof established Feige’s lower bound: for independent nonnegative mean-one variables, the probability their sum is below n+1 is at least (n/(n+1))^n.', 'proved', 'human-ai', 'Probability', '2026-07-27', 'GPT-5.6 Sol', 'Assisted in obtaining the short proof and connecting it to recent work on Gaffke’s conjecture.', 'Zipei Nie and Jiaye Wei checked, wrote, and released the argument.', 'Author-checked public preprint.', 'expert', 'The precise degree of AI autonomy is not quantified beyond the authors’ assistance statement.', 0, '["Feige conjecture","probability","inequalities"]');
